  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Solifenacin absolute oral bioavailability was 88.0% (95% CI 75.8–102.1) in healthy male volunteers after a 10 mg oral dose versus IV, supporting F >= 20%."
    },
    {
      "card_ids": ["C03"],
      "claim": "Zolpidem absolute bioavailability was about 70% in healthy young male volunteers after a 5 mg oral dose versus IV, supporting F >= 20%."
    },
    {
      "card_ids": ["C41"],
      "claim": "Quinapril absolute bioavailability was 45.9% (SD 11.2) in healthy participants after a 20 mg oral dose versus intravenous quinaprilat, supporting F >= 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All 10 evidence molecules support high oral bioavailability at the F>=20% threshold. Numeric absolute values range from 20–40% (celecoxib) to 88% (solifenacin), with multiple direct human absolute bioavailability measurements above 20%; qualitative 'high' records are consistent. Therefore predict high.",
  "evidence_gaps": [
    "Some records are qualitative ('high') rather than numeric, but numeric absolute records are sufficient.",
    "One record labels 20–40% as 'low' despite meeting the threshold; qualitative label does not override numeric value."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C06", "C03", "C41"],
  "revision_action": "initial",
  "supportive_card_ids": ["C06", "C03", "C41"]
}

